import pub.developers.forum.api.model.ResultModel;
import pub.developers.forum.portal.support.WebUtil;

import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

@SpringBootTest
@AutoConfigureMockMvc
class UserControllerTest {

    private UserController userController;

    private MockMvc mockMvc;

    @BeforeEach
    void setUp() {
        userController = new UserController();
        mockMvc = MockMvcBuilders.standaloneSetup(userController).build();
    }

    @Test
    void testLogout() throws Exception {
        MvcResult mvcResult = mockMvc.perform(get("/user/logout")
                .contentType(MediaType.APPLICATION_FORM_URLENCODED)
                .cookie(new Cookie("sid", "123")))
                .andExpect(status().isOk())
                .andExpect(cookie().doesNotExist("sid"))
                .andReturn();

        ResultModel resultModel = ResultModel.builder()
                .code(200)
                .message("成功")
                .data("pub.developers.forum.portal.controller.WebConst.REQUEST_REDIRECT_PREFIX")
                .build();

        String content = mvcResult.getResponse().getContentAsString();
        assertEquals(JSON.toJSONString(resultModel), content);
    }

    private String login(String email, String pwd) throws Exception {
        return mockMvc.perform(post("/user/login")
                .contentType(MediaType.APPLICATION_FORM_URLENCODED)
                .param("email", email)
                .param("pwd", WebUtil.md5((email + pwd).getBytes())))
                .andExpect(status().isOk())
                .andExpect(content().contentType(MediaType.APPLICATION_JSON))
                .andExpect(jsonPath("$.code").value(200))
                .andExpect(jsonPath("$.token").exists())
                .andReturn().getResponse().getContentAsString();
    }
}

