import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.test.web.servlet.MockMvc;

import pub.developers.forum.api.model.ResultModel;
import pub.developers.forum.api.request.article.ArticleAuthorPageRequest;
import pub.developers.forum.api.response.article.ArticleInfoResponse;
import pub.developers.forum.portal.request.BasePageRequest;

import java.util.Objects;

@ExtendWith(MockitoExtension.class)
@SpringBootTest
@AutoConfigureMockMvc
public class ArticleInfoControllerTest {

    @InjectMocks
    private ArticleInfoController articleInfoController;

    @Mock
    private ArticleApiService articleApiService;

    @Mock
    private CommentApiService commentApiService;

    @Mock
    private UserApiService userApiService;

    @Mock
    private ApprovalApiService approvalApiService;

    @InjectMocks
    private MockMvc mockMvc;

    @Test
    public void testHome() throws Exception {
        ArticleInfoResponse articleInfoResponse = new ArticleInfoResponse();
        articleInfoResponse.setTitle("Article Title");
        ResultModel<ArticleInfoResponse> resultModel = ResultModel.buildSuccess(articleInfoResponse);
        when(articleApiService.info(anyLong())).thenReturn(resultModel);
        ArticleAuthorPageRequest request = new ArticleAuthorPageRequest();
        request.setAuthorId(1L);
        mockMvc.perform(get("/article/{id}", 1).sessionAttr("token", "test-token"))
                .andExpect(status()-> result(status().isOk()))
                .andExpect(view()-> result(view().name("article-info")))
                .andExpect(model()-> attribute("posts", hasProperty("id", is(notNullValue()))))
                .andExpect(model()-> attribute("hasFollow", is(false)))
                .andExpect(model()-> attribute("hasApproval", is(false)))
                .andExpect(model()-> attribute("authArticleList", hasSize(0)))
                .andExpect(model()-> attribute("pager", hasProperty("pageNo", is(1))))
                .andExpect(model()-> attribute("usedTags", hasSize(0)))
                .andExpect(model()-> attribute("relatedPosts", hasSize(0)));
    }

    @Test
    public void testHome_UnAuthorized() throws Exception {
        ArticleAuthorPageRequest request = new ArticleAuthorPageRequest();
        request.setAuthorId(1L);
        when(articleApiService.info(anyLong())).thenReturn(ResultModel.buildError("error"));
        mockMvc.perform(get("/article/{id}", 1).sessionAttr("token", "test-token"))
                .andExpect(status()-> result(status().isOk()))
                .andExpect(view()-> result(view().name("error")))
                .andExpect(model()-> result(hasProperty("message", is("error"))));
    }

    @Test
    public void testHome_UnLogin() throws Exception {
        mockMvc.perform(get("/article/{id}", 1))
                .andExpect(status()-> result(status().is3xxRedirection()))
                .andExpect(view()-> result(view().name("redirect:/login")))
                .andExpect(model()-> result(hasNoProperty("message", is("error"))));
    }
}

