@RunWith(MockitoJUnitRunner.class)
public class MessageControllerTest {

    @InjectMocks
    private MessageController messageController;

    @Mock
    private MessageApiService messageApiService;

    @Mock
    private GlobalViewConfig globalViewConfig;

    @Mock
    private WebUtil webUtil;

    @Mock
    private Model model;

    private MockHttpServletRequest request;
    private MockHttpServletResponse response;

    @Before
    public void setUp() {
        MockitoAnnotations.initMocks(this);
        request = new MockHttpServletRequest();
        RequestContextHolder.setRequestAttributes(new ServletRequestAttributes(request));
        response = new MockHttpServletResponse();
    }

    @Test
    public void testIndex() {
        MessageRequest messageRequest = new MessageRequest();
        messageRequest.setPageNo(1);
        messageRequest.setPageSize(10);

        when(messageApiService.page(any())).thenReturn(ResultModel.builder().data(PageResponseModel.builder().list(new ArrayList<MessagePageResponse>()).total(0L).build()).build());

        String view = messageController.index(messageRequest, model, request);
        assertEquals("message", view);

        messageRequest.setType("用户关注");

        when(messageApiService.page(any())).thenReturn(ResultModel.builder().data(PageResponseModel.builder().list(new ArrayList<MessagePageResponse>()).total(1L).build()).build());

        view = messageController.index(messageRequest, model, request);
        assertEquals("message", view);
    }
}

package pub.developers.forum.portal.controller;

import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import org.mockito.junit.MockitoJUnitRunner;
import org.springframework.mock.web.MockHttpServletRequest;
