import org.springframework.test.web.servlet.setup.MockMvcBuilders;
import pub.developers.forum.api.model.ResultModel;
import pub.developers.forum.api.response.user.UserInfoResponse;
import pub.developers.forum.api.service.UserApiService;
import pub.developers.forum.common.enums.UserRoleEn;
import pub.developers.forum.portal.support.ViewException;
import pub.developers.forum.portal.support.WebUtil;

import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

@RunWith(MockitoJUnitRunner.class)
public class VueControllerTest {

    private MockMvc mockMvc;

    @InjectMocks
    private VueController vueController;

    @Mock
    private UserApiService userApiService;

    @Before
    public void setUp() {
        MockitoAnnotations.initMocks(this);
        mockMvc = MockMvcBuilders.standaloneSetup(vueController).build();
    }

    @Test(expected = ViewException.class)
    public void testAdmin_no_sid() throws Exception {
        mockMvc.perform(get("/admin"))
                .andExpect(status().isOk())
                .andExpect(view().name("vue-admin"))
                .andExpect(exception().hasCause(ViewException.class))
                .andExpect(result -> assertEquals("用户未登录", result.getResolvedException().getMessage()));
    }

    @Test(expected = ViewException.class)
    public void testAdmin_user_info_fail() throws Exception {
        when(userApiService.info(WebUtil.cookieGetSid(new MockHttpServletRequest())))
                .thenReturn(ResultModel.error("用户信息获取失败"));
        mockMvc.perform(get("/admin")
                .cookie(new Cookie(WebUtil.cookieGetSid(new MockHttpServletRequest()), "token")))
                .andExpect(status().isOk())
                .andExpect(view().name("vue-admin"))
                .andExpect(exception().hasCause(ViewException.class))
                .andExpect(result -> assertEquals("用户信息获取失败", result.getResolvedException().getMessage()));
    }

    @Test(expected = ViewException.class)
    public void testAdmin_no_data() throws Exception {
        when(userApiService.info(WebUtil.cookieGetSid(new MockHttpServletRequest())))
                .thenReturn(ResultModel.success(null));
        mockMvc.perform(get("/admin")
                .cookie(new Cookie(WebUtil.cookieGetSid(new MockHttpServletRequest()), "token")))
                .andExpect(status().isOk())
                .andExpect(view().name("vue-admin"))
                .andExpect(exception().hasCause(ViewException.class))
                .andExpect(result -> assertEquals("用户信息获取失败", result.getResolvedException().getMessage()));
    }

    @Test(expected = ViewException.class)
    public void testAdmin_user_role_error() throws Exception {
        when(userApiService.info(WebUtil.cookieGetSid(new MockHttpServletRequest())))
                .thenReturn(ResultModel.success(UserInfoResponse.builder().role(UserRoleEn.USER.getValue()).build()));
        mockMvc.perform(get("/admin")
                .cookie(new Cookie(WebUtil.cookieGetSid(new MockHttpServletRequest()), "token")))
                .andExpect(status().isOk())
                .andExpect(view().name("vue-admin"))
                .andExpect(exception().hasCause(ViewException.class))
                .andExpect(result -> assertEquals("无权限访问", result.getResolvedException().getMessage()));
    }

    @Test
    public void testAdmin_success() throws Exception {
        when(userApiService.info(WebUtil.cookieGetSid(new MockHttpServletRequest())))
                .thenReturn(ResultModel.success(UserInfoResponse.builder().role(UserRoleEn.ADMIN.getValue()).build()));
        mockMvc.perform(get("/admin")
                .cookie(new Cookie(WebUtil.cookieGetSid(new MockHttpServletRequest()), "token")))
                .andExpect(status().isOk())
                .andExpect(view().name("vue-admin"));
    }
}

package pub.developers.forum.portal.controller;

import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.InjectMocks;
