import org.mockito.MockitoAnnotations;
import org.springframework.http.MediaType;
import org.springframework.test.context.junit4.SpringJUnit4ClassRunner;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.setup.MockMvcBuilders;
import org.springframework.web.context.WebApplicationContext;

import pub.developers.forum.api.model.PageResponseModel;
import pub.developers.forum.api.model.ResultModel;
import pub.developers.forum.api.service.SearchApiService;
import pub.developers.forum.api.vo.PostsVO;
import pub.developers.forum.portal.request.SearchRequest;
import pub.developers.forum.portal.support.GlobalViewConfig;
import pub.developers.forum.portal.support.WebUtil;

import java.util.ArrayList;
import java.util.List;

import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

@RunWith(SpringJUnit4ClassRunner.class)
public class SearchControllerTest {

    @InjectMocks
    private SearchController searchController;

    @Mock
    private SearchApiService searchApiService;

    @Mock
    private WebUtil webUtil;

    @Mock
    private GlobalViewConfig globalViewConfig;

    private MockMvc mockMvc;

    @Before
    public void setUp() {
        MockitoAnnotations.initMocks(this);
        mockMvc = MockMvcBuilders.standaloneSetup(searchController).build();
    }

    @Test
    public void testIndex_success() throws Exception {
        SearchRequest searchRequest = new SearchRequest();
        searchRequest.setKey("test");
        PageResponseModel<PostsVO> pageResponseModel = new PageResponseModel<>();
        pageResponseModel.setList(new ArrayList<>());
        pageResponseModel.setTotal(0L);
        ResultModel<PageResponseModel<PostsVO>> resultModel = ResultModel.builder().data(pageResponseModel).build();
        when(searchApiService.pagePostsSearch(any())).thenReturn(resultModel);

        mockMvc.perform(get("/search").param("key", "test").contentType(MediaType.APPLICATION_FORM_URLENCODED))
                .andExpect(status().isOk())
                .andExpect(view().name("search"))
                .andExpect(model().attributeExists("postsList", "pager"))
                .andExpect(model().attribute("postsList", hasSize(0)))
                .andExpect(model().attribute("pager", hasProperty("total", is(0L))))
                .andExpect(model().attribute("pager", hasProperty("pageSize", is(20))))
                .andExpect(model().attribute("pager", hasProperty("currentPage", is(1))));

        verify(searchApiService, times(1)).pagePostsSearch(any());
        verify(webUtil, times(1)).buildPostsList(anyList());
        verify(webUtil, times(1)).buildArticles(anyList());
    }

    @Test
    public void testIndex_failure() throws Exception {
        SearchRequest searchRequest = new SearchRequest();
        searchRequest.setKey("test");
        ResultModel<PageResponseModel<PostsVO>> resultModel = ResultModel.builder().success(Boolean.FALSE).build();
        when(searchApiService.pagePostsSearch(any())).thenReturn(resultModel);

        mockMvc.perform(get("/search").param("key", "test").contentType(MediaType.APPLICATION_FORM_URLENCODED))
                .andExpect(status().isOk())
                .andExpect(view().name("search"))
                .andExpect(model().attributeExists("postsList", "pager"))
                .andExpect(model().attribute("postsList", hasSize(0)))
                .andExpect(model().attribute("pager", hasProperty("total", is(0L))))
                .andExpect(model().attribute("pager", hasProperty("pageSize", is(20))))
                .andExpect(model().attribute("pager", hasProperty("currentPage", is(1))));

        verify(searchApiService, times(1)).pagePostsSearch(any());
        verify(webUtil, times(1)).buildPostsList(anyList());
        verify(webUtil, times(1)).buildArticles(anyList());
    }
}
